head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF30641.xml";
scwin.gLastJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


//저장버튼 클릭 시
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(txb_FILE) == '') {
        $c.win.alert("[첨부파일]을 선택하세요.");
        file.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        //setObjectValue(txb_acpt_ddtm,"");
        scwin.gLastJob = "저장";
        trs_Save.Action = "/ListedCompany.do?method=procInsertDisclsProfsAhthExcelFile&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.Post();
    }
};




// 저장 에러 발생 시
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};





//파일첨부 버튼 클릭 시
scwin.fn_SelectAttach = function() {
    var vFile = file.getValue();
    if (vFile == "") {
        return;
    } else if (vFile.substring(vFile.length - 3, vFile.length).toUpperCase() != "XLS") {
        $c.win.alert("엑셀파일(*.xls)만 입력하시기 바랍니다.");
        txb_FILE.setValue("");
        return;
    } else {
        txb_FILE.setValue(file.getValue());
        dts_FileList.setCellData(1, "fileInfo", file.getValue());
        dts_FileList.setCellData(1, "fileUrl", file.getValue());
    }
};





// 초기화
scwin.fn_Init = function() {
    //파일업로드 데이터셋 초기화

    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    $c.frame.path("../").gIsFirstSch = true;
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.file_OnClick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_FORM_U1_onclick = function() {
    location.href = "/issueinfo/discls_ahth_sample.xls";
};
scwin.gform_onload = function() {
    frame.width = 580;
    frame.height = 230;

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_Init();
};
